(function(root){
  const engine=root.EntryEngine||(typeof require==='function'?require('./engine.js'):null);
  const layers=root.EntryLayers||(typeof require==='function'?require('./layers.js'):null);
  const fields={fear:['VIX 分位','≥ 80'],drawdown:['60日回撤','≤ −15%'],stabilize:['收复前日高点','> 0%'],volume:['量比','≥ 1（低吸）/ ≥ 1.2（趋势）'],market:['SPY MA200','> 0%'],sector:['行业趋势（SOXX MA50）','> 0%'],breadth:['行业广度','≥ 60%'],stock:['个股 MA50','> 0% 且 ≤ 10%'],upside:['估值空间','≥ 15%（低吸）/ ≥ 5%（趋势）'],revision:['共识修正','≥ −5%（低吸）/ ≥ 0%（趋势）']};
  const valid=(d,k)=>{const f=(engine.definitions).find(x=>x[0]===k);return typeof d?.[k]==='number'&&Number.isFinite(d[k])&&(!f|| (d[k]>=f[2]&&d[k]<=f[3]));};
  const item=(d,k,ok)=>({key:k,label:fields[k][0],target:fields[k][1],status:valid(d,k)?(ok?'met':'unmet'):'missing',value:valid(d,k)?d[k]:null});
  function path(d,name,sources){const trend=name==='trend';const checks=trend?[item(d,'market',d.market>0),item(d,'sector',d.sector>0),item(d,'breadth',d.breadth>=60),item(d,'stock',d.stock>0&&d.stock<=10),item(d,'volume',d.volume>=1.2),item(d,'upside',d.upside>=5),item(d,'revision',d.revision>=0)]:[item(d,'fear',d.fear>=80),item(d,'drawdown',d.drawdown<=-15),item(d,'stabilize',d.stabilize>0),item(d,'volume',d.volume>=1),item(d,'upside',d.upside>=15),item(d,'revision',d.revision>=-5)];const alignment=trend?d.aligned===false:d.panicAligned===false;if(alignment)checks.unshift({key:'alignment',label:trend?'路径日期对齐':'VIX 与价格日期对齐',target:'同一完成日线',status:'missing',value:null});const blockers=[];if(d.broken==='yes')blockers.push('基本面已失效，否决该路径。');if(alignment)blockers.push('跨资产日期未对齐，暂停该路径。');const missing=checks.filter(x=>x.status==='missing').map(x=>{if(x.key==='market'){const s=sources.find(v=>v.symbol==='SPY'&&Number.isFinite(v.count)&&Number.isFinite(v.requiredHistory));if(s&&s.count<s.requiredHistory)return `${x.label}：已有 ${s.count} / 需要 ${s.requiredHistory} 根日线`; }return x.label});const unmet=checks.filter(x=>x.status==='unmet').map(x=>x.label+'（需 '+x.target+'）');const result=engine.evaluate(d);const complete=result[name].every(x=>x.status==='yes')&&d.broken==='no';return{name,complete,checks,missing,unmet,blockers,next:complete?['等待新证据并复核来源日期。']:d.broken==='yes'?['重新核实经营假设；恢复前暂停买入。']:[...missing.map(x=>'补齐'+x+'。'),...unmet.map(x=>'等待'+x+'。'),...blockers]};}
  function completeness(d={},sources=[],mode='auto'){const panic=path(d,'panic',sources),trend=path(d,'trend',sources);const all=panic.checks.concat(trend.checks);const observed=layers(d);const technical=observed.dip||observed.trend;if(d.broken!=='no'&&d.broken!=='yes'){[panic,trend].forEach(p=>{p.missing.push('基本面状态（需核实未失效）');p.next.push('补齐基本面状态：核实经营假设未失效。');});}let currentPhase;if(d.broken==='yes')currentPhase='blocked';else if(mode!=='auto')currentPhase='manual';else if(panic.complete||trend.complete)currentPhase='complete';else if(technical)currentPhase='technical_candidate_pending';else if(all.some(x=>x.status==='unmet'))currentPhase='unmet';else currentPhase='missing';return{currentPhase,mode,isScenario:mode!=='auto',actionAllowed:mode==='auto'&&currentPhase==='complete',independence:'低吸与趋势两条路径独立判断；一条路径缺数据不压制另一条路径。',paths:{panic,trend},next:[...new Set([...panic.next,...trend.next])].slice(0,8)};}
  root.EntryCompleteness=completeness;if(typeof module!=='undefined')module.exports=completeness;
})(globalThis);
